import{_ as n,o as a,c as t,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"OpenHands Agent Canvas — Engineering Analysis","description":"","frontmatter":{"title":"OpenHands Agent Canvas — Engineering Analysis","outline":"deep"},"headers":[],"relativePath":"engineering/openhands.md","filePath":"engineering/openhands.md","lastUpdated":1785568227000}'),o={name:"engineering/openhands.md"};function s(l,e,r,d,p,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="openhands-agent-canvas-openhands-工程分析" tabindex="-1">OpenHands Agent Canvas / OpenHands 工程分析 <a class="header-anchor" href="#openhands-agent-canvas-openhands-工程分析" aria-label="Permalink to &quot;OpenHands Agent Canvas / OpenHands 工程分析&quot;">​</a></h1><h2 id="engineering-direction-工程方向" tabindex="-1">Engineering direction / 工程方向 <a class="header-anchor" href="#engineering-direction-工程方向" aria-label="Permalink to &quot;Engineering direction / 工程方向&quot;">​</a></h2><p>OpenHands is evolving from a coding Agent project toward an operator-facing Agent workspace. Agent Canvas emphasizes self-hosting, skills and plugins, connection health, desktop packaging, automation triggers and multi-environment execution.</p><p>OpenHands 正从 Coding Agent 演进为面向操作者的 Agent 工作空间。Agent Canvas 强化自托管、Skill/Plugin、连接健康、桌面封装、自动触发与多环境执行。</p><h2 id="runtime-pattern-runtime-模式" tabindex="-1">Runtime pattern / Runtime 模式 <a class="header-anchor" href="#runtime-pattern-runtime-模式" aria-label="Permalink to &quot;Runtime pattern / Runtime 模式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent Harness</span></span>
<span class="line"><span>  + Skills and Plugins</span></span>
<span class="line"><span>  + Connection Health</span></span>
<span class="line"><span>  + Local / Remote Runtime</span></span>
<span class="line"><span>  + Manual / Scheduled / Event Trigger</span></span>
<span class="line"><span>  + Operator Console</span></span></code></pre></div><p>The important lesson is that long-running AI work requires more than model capability. It needs deployment visibility, restartability, health state, tool packaging and human operation.</p><h2 id="capabilities-worth-tracking-值得跟踪的能力" tabindex="-1">Capabilities worth tracking / 值得跟踪的能力 <a class="header-anchor" href="#capabilities-worth-tracking-值得跟踪的能力" aria-label="Permalink to &quot;Capabilities worth tracking / 值得跟踪的能力&quot;">​</a></h2><ul><li>explicit skill installation and activation;</li><li>plugin-content visibility;</li><li>connection-health diagnostics;</li><li>startup logs;</li><li>desktop experience;</li><li>scheduled and event-triggered automation;</li><li>local, hosted and enterprise runtime options.</li></ul><h2 id="what-codeflowmu-should-learn-codeflowmu-应学习" tabindex="-1">What CodeFlowMu should learn / CodeFlowMu 应学习 <a class="header-anchor" href="#what-codeflowmu-should-learn-codeflowmu-应学习" aria-label="Permalink to &quot;What CodeFlowMu should learn / CodeFlowMu 应学习&quot;">​</a></h2><ol><li><strong>Connection health as a first-class state.</strong> Provider and tool failures should be visible and actionable.</li><li><strong>Activation lifecycle.</strong> Installing a Skill is different from activating and validating it.</li><li><strong>Operator diagnostics.</strong> Startup, session and recovery logs should be understandable without reading raw runtime files.</li><li><strong>Multiple trigger modes.</strong> Manual, scheduled and event-driven work should share one WorkOrder model.</li><li><strong>Self-hosted deployment.</strong> SME adoption benefits from a local-first path.</li></ol><h2 id="what-codeflowmu-should-not-copy-不应照搬" tabindex="-1">What CodeFlowMu should not copy / 不应照搬 <a class="header-anchor" href="#what-codeflowmu-should-not-copy-不应照搬" aria-label="Permalink to &quot;What CodeFlowMu should not copy / 不应照搬&quot;">​</a></h2><ul><li>Agent workspace as the primary product abstraction;</li><li>feature breadth without Position, ownership and completion contracts;</li><li>coding-centric assumptions inside the general Core;</li><li>one UI trying to expose every low-level backend concept.</li></ul><h2 id="differentiation-差异化" tabindex="-1">Differentiation / 差异化 <a class="header-anchor" href="#differentiation-差异化" aria-label="Permalink to &quot;Differentiation / 差异化&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenHands primary abstraction:</span></span>
<span class="line"><span>Agent workspace and automation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CodeFlowMu target abstraction:</span></span>
<span class="line"><span>Position + WorkOrder + governed workflow + Runtime + evidence</span></span></code></pre></div><p>OpenHands can potentially become an Agent Provider or execution harness beneath CodeFlowMu. The organizational Position, TeamPolicy, FCoP responsibility, TMPA evidence and completion gates should remain stable above it.</p><h2 id="recommended-codeflowmu-response-建议响应" tabindex="-1">Recommended CodeFlowMu response / 建议响应 <a class="header-anchor" href="#recommended-codeflowmu-response-建议响应" aria-label="Permalink to &quot;Recommended CodeFlowMu response / 建议响应&quot;">​</a></h2><ul><li>unify provider, tool, session and Agent health in the runtime console;</li><li>expose restart, retry, release, switch-provider and recovery actions;</li><li>display which Skill and version were actually loaded;</li><li>retain semantic business events separately from low-level logs;</li><li>avoid scheduling development solely to match OpenHands release lists.</li></ul><h2 id="strategic-judgment-战略判断" tabindex="-1">Strategic judgment / 战略判断 <a class="header-anchor" href="#strategic-judgment-战略判断" aria-label="Permalink to &quot;Strategic judgment / 战略判断&quot;">​</a></h2><p>OpenHands is a high-value engineering benchmark for Agent operations. It is not yet a substitute for the Position-centric Digital Employee architecture pursued by CodeFlowMu.</p>`,20)])])}const g=n(o,[["render",s]]);export{u as __pageData,g as default};
